function prepare(f){const p=plan.recordPeerOriginQuarantinePlan(f.root,actor,f.input);return {...p,review_ids:['review-reviewer']};}
function mechanical(f,p,role){
 const id='job-'+role,instance='instance-'+role,job={id,instance_id:instance,role:'qa',host:'codex',epoch:9,status:'queued',native_id:null,review_of:{id:p.plan_id,revision:1},context_sha256:'synthetic-original-context',session_key:'qa:'+role,inputs:[],requester:{role:'cos',host:'codex',session_id:actor.session_id,epoch:9},created_at:new Date().toISOString()};
 f.write('job.queued',s=>{s.jobs[id]=job;s.sessions[job.session_key]={instance_id:instance,role:'qa',native_id:null,host:'codex'};return s;});
 f.write('job.started',s=>{Object.assign(s.jobs[id],{status:'running',started_at:new Date().toISOString(),worker_pid:4000});return s;});
 const invocation={invocation_id:'invocation-'+role,job_id:id,instance_id:instance,worker_pid:4000,host:'codex',requested_at:new Date().toISOString()};f.write('job.model_process.requested',s=>{requestModelProcess(s.jobs[id],invocation);return s;});
 const birth={protocol:'ordinary-model-process-birth-v1',launch_id:'launch-'+role,host:'codex',pid:4001,worker_pid:4000,spawned_at:new Date().toISOString(),command_sha256:digest('source-only'),argv_sha256:digest('source-only'),cwd_sha256:digest(f.root)};f.write('job.model_process.born',s=>{recordModelProcessBirth(s.jobs[id],invocation,birth);return s;});
 const closure={protocol:'ordinary-model-process-close-v1',birth_sha256:digest(JSON.stringify(birth)),closed_at:new Date().toISOString(),exit_code:0,signal:null,observation:'original-child-close'};f.write('job.model_process.closed',s=>{recordModelProcessClosure(s.jobs[id],invocation,birth,closure);return s;});
 f.write('job.completed',s=>{const j=s.jobs[id],rid='review-'+role;Object.assign(j,{status:'completed',native_id:'synthetic-native-'+role,artifact_id:rid,finished_at:new Date().toISOString(),coordination_release:{termination_confirmed:true,reason:'model_process_closed',at:new Date().toISOString()}});s.sessions[j.session_key].native_id=j.native_id;s.records[rid]={id:rid,kind:'review',status:'Submitted',revision:1,author_role:'qa',author_instance:instance,job_id:id,review_of:j.review_of,review:{verdict:'Pass',reason:'Synthetic source mechanics only.',blockers:[]},content:JSON.stringify({protocol:'peer-origin-mechanical-review-v1',permitted_action:'quarantine_peer_origin',plan_sha256:p.plan_sha256,cut_sha256:p.cut_sha256,maintenance_role:role,legacy_authority:'retired-without-conversion',execution_resumed:false}),created_at:new Date().toISOString()};return s;});
}
function reviewed(f){const p=prepare(f);mechanical(f,p,'reviewer');return p;}
const apply=(f,p)=>quarantine.quarantinePeerOrigin(f.root,actor,{plan_id:p.plan_id,review_ids:p.review_ids,source_instruction:'Fictional exact reviewed quarantine; remain paused.'});
function smallPins(){const team={plugin_version:'0.7.8',governance:'Fictional original governance. All UNKNOWNs and limits remain.',governance_sha256:digest('Fictional original governance. All UNKNOWNs and limits remain.'),roles:{cos:{instructions:'Fictional coordinator.'},qa:{instructions:'Fictional independent reviewer.'}},cos_instructions:'Fictional owner instructions remain exact.'};return {...team,team_sha256:teamHash(team)};}
function quarantined(t,changes={}){const f=fixture(t,{...smallPins(),...changes});f.input.maintenance={...f.input.maintenance,max_model_calls:8,max_review_calls:4};f.input.policy.max_model_calls=10;const p=reviewed(f),result=apply(f,p),ledger=new PeerLedger(f.root);t.after(()=>ledger.close());const api=maintenance.createPeerOriginMaintenance({ledger,actor}),sources=ledger.read(tx=>{const o=tx.get('control','origin'),d=o.value.manifest.original_sources;return d.pages.flatMap(p=>tx.getVersion(p).value.items);});return {...f,p,result,ledger,api,sources};}
function native(f,cap,id){const b=maintenance.inspectOriginalPeerOriginMaintenance(cap),facts={protocol:'peer-origin-original-creation-v1',kind:b.kind,admission_ref:b.admission_ref,context_sha256:b.context_sha256,native_id:id,thread_id:id,process:{pid:9901,started_at:'2026-11-12T00:00:00.000Z'},build:{executable_sha256:'a'.repeat(64),source_manifest_sha256:'b'.repeat(64),host_instance_id:'synthetic-host'},launch_nonce_sha256:'c'.repeat(64),creation_request_sha256:'d'.repeat(64),creation_response_sha256:'e'.repeat(64),creation_tools_sha256:'f'.repeat(64),profile_id:'soloco-origin-maintenance-readonly-v1'};maintenance.bindOriginalPeerOriginNative(cap,domain.mintSyntheticBirth(f.ledger,facts));return {cap,binding:maintenance.inspectOriginalPeerOriginMaintenance(cap)};}
function consumeOrigin(cap){const channel=maintenance.originalPeerOriginMaintenanceChannel(cap),h=channel.header();let text='';for(let offset=0;offset<h.total_characters;){const part=channel.read({sha256:h.sha256,offset,length:4096});text+=part.text;offset+=part.length;}assert.equal(peerDigest(JSON.parse(text)),h.sha256);return {channel,h,text};}
function segments(f){return f.sources.map(s=>({source_id:s.source_id,sha256:s.sha256,offset:0,length:s.characters}));}
async function finish(f,cap,id,{verdict='Pass'}={}){const n=native(f,cap,id),{channel,h}=consumeOrigin(cap),b=n.binding;const output=b.kind==='peer-origin-reconstruction'?{protocol:'peer-origin-reconstruction-result-v1',subject:h.review_subject,mappings:b.subject.segments.map(({source_id,sha256,offset,length})=>({source_id,sha256,offset,length,disposition:'retain-global',reason:'Preserve complete original as compulsory global DATA.'})),reason:'Synthetic source mechanics only.'}:{protocol:'peer-origin-independent-review-result-v1',subject:h.review_subject,reconstruction_ref:b.reconstruction_ref,verdict,reason:'Synthetic exact range review only.',blockers:verdict==='Pass'?[]:['Retain synthetic negative.'],permitted_action:'seal_peer_origin_ranges'};const text=canonical(output);channel.submit({sha256:h.sha256,content:text});const facts={protocol:'peer-owned-admitted-task-drain-v1',kind:b.kind,admission_ref:b.admission_ref,context_sha256:b.context_sha256,native_id:id,thread_id:id,turn_id:'synthetic-turn',terminal_status:'completed',output:text,output_sha256:digest(text),group_absent:null,remote_domain_closed:false};return {...n,output,text,token:domain.mintSyntheticDrain(f.ledger,facts)};}
function peerEvents(f){return f.ledger.db.prepare('SELECT * FROM peer_events ORDER BY seq').all();}
function entireSql(f){const schema=f.ledger.db.prepare("SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name").all(),rows={};for(const s of schema)if(s.type==='table')rows[s.name]=f.ledger.db.prepare('SELECT * FROM "'+s.name.replaceAll('"','""')+'"').all().map(canonical).sort();return peerDigest({schema,rows});}

