// Original independent counter bodies retained below for repair regression.
// Independent bounded counter cases. Original fixture's synthetic context and
// native seams are unchanged; these exercise only toy SQLite quarantine guards.
test('INDEPENDENT final expiry must hold after the actual staged-row fence read',t=>{
 const f=fixture(t),p=reviewed(f),nativePrepare=DatabaseSync.prototype.prepare,now=Date.now;
 const end=Date.parse(f.state().records[p.plan_id].origin_quarantine_plan.expires_at);
 let hit=0,threw=false,error,result;
 DatabaseSync.prototype.prepare=function(sql,...rest){
  const statement=Reflect.apply(nativePrepare,this,[sql,...rest]);
  if(sql==="SELECT tbl_name,sql FROM sqlite_master WHERE type='trigger' AND name=?"){
   const get=statement.get,db=this;
   statement.get=function(...args){
    const row=Reflect.apply(get,this,args);
    const exists=Reflect.apply(nativePrepare,db,["SELECT 1 FROM sqlite_master WHERE type='table' AND name='peer_rows'"]).get();
    if(!hit&&exists&&db.isTransaction&&Reflect.apply(nativePrepare,db,["SELECT COUNT(*) AS n FROM peer_rows WHERE family='control' AND id='origin'"]).get().n===1){hit++;Date.now=()=>end+1;}
    return row;
   };
  }
  return statement;
 };
 try{result=apply(f,p);}catch(e){threw=true;error=e;}finally{DatabaseSync.prototype.prepare=nativePrepare;Date.now=now;}
 const actual=f.db(db=>({layout:db.prepare('SELECT version FROM company_layout WHERE id=1').get().version}));
 assert.equal(hit,1,'Must cross expiry during actual final fence SQL after own control/origin reached storage');
 t.diagnostic('INDEPENDENT_ACTUAL '+JSON.stringify({case:'late-expiry',hit,threw,code:error?.code??null,message:error?.message??null,result_status:result?.status??null,actual}));
 assert.throws(()=>{if(threw)throw error;},e=>e.code==='ORIGIN_PLAN_EXPIRED');
});

test('INDEPENDENT changed non-tail original event metadata must hold',t=>{
 const f=fixture(t);f.write('fixture.additional-prebaseline',s=>{s.prebaseline_counter='preserve';return s;});
 const p=reviewed(f),planValue=f.state().records[p.plan_id].origin_quarantine_plan;
 const old=planValue.cut.events.find(e=>e.seq<planValue.baseline.seq);assert(old,'Need a real original event before the intake anchor');
 const changed=f.db(db=>db.prepare('UPDATE events SET at=?,type=? WHERE seq=?').run('2000-01-01T00:00:00.000Z','counter.altered-original-metadata',old.seq).changes);assert.equal(changed,1);
 let threw=false,error,result;try{result=apply(f,p);}catch(e){threw=true;error=e;}
 const actual=f.db(db=>({layout:db.prepare('SELECT version FROM company_layout WHERE id=1').get().version,event:db.prepare('SELECT seq,at,type FROM events WHERE seq=?').get(old.seq)}));
 t.diagnostic('INDEPENDENT_ACTUAL '+JSON.stringify({case:'old-event-metadata',changed,old_seq:old.seq,baseline_seq:planValue.baseline.seq,threw,code:error?.code??null,message:error?.message??null,result_status:result?.status??null,actual}));
 assert.throws(()=>{if(threw)throw error;},e=>e.code==='ORIGIN_ARCHIVE_CHANGED');
});

